export interface InvoicesResource {
  /**
   * Create an invoice.
   *
   * A draft, for a customer; it finalizes on its own when `auto_advance` is set.
   *
   * `POST /v1/invoices`
   */
  create(
    params: BodyOf<Op<'createInvoice'>>,
    options?: RequestOptions & IdempotencyOptions,
  ): Promise<ResponseOf<Op<'createInvoice'>>>;
  /**
   * List invoices.
   *
   * `GET /v1/invoices`
   */
  list(
    params?: QueryOf<Op<'listInvoices'>>,
    options?: RequestOptions,
  ): ListPromiseOf<Op<'listInvoices'>>;
  /**
   * Preview the upcoming invoice.
   *
   * The invoice a customer's subscription will renew with — or, with `subscription_items`, the one a change would produce. Computed, never stored (its `id` is empty). 404 when the customer has no subscription that will renew.
   *
   * `GET /v1/invoices/upcoming`
   */
  retrieveUpcoming(
    params: QueryOf<Op<'retrieveUpcomingInvoice'>>,
    options?: RequestOptions,
  ): Promise<ResponseOf<Op<'retrieveUpcomingInvoice'>>>;
  /**
   * Retrieve an invoice.
   *
   * `GET /v1/invoices/{id}`
   */
  retrieve(
    id: string,
    params?: QueryOf<Op<'retrieveInvoice'>>,
    options?: RequestOptions,
  ): Promise<ResponseOf<Op<'retrieveInvoice'>>>;
  /**
   * Update an invoice.
   *
   * Drafts only, except `metadata` and `auto_advance`. A field sent as `""` is cleared; `metadata` is a patch.
   *
   * `POST /v1/invoices/{id}`
   */
  update(
    id: string,
    params?: BodyOf<Op<'updateInvoice'>>,
    options?: RequestOptions & IdempotencyOptions,
  ): Promise<ResponseOf<Op<'updateInvoice'>>>;
  /**
   * Delete a draft invoice.
   *
   * Only a draft can be deleted; a finalized invoice is voided instead.
   *
   * `DELETE /v1/invoices/{id}`
   */
  del(id: string, options?: RequestOptions): Promise<ResponseOf<Op<'deleteInvoice'>>>;
  /**
   * Finalize a draft invoice.
   *
   * It gets its number, its tax and its payer-facing page.
   *
   * `POST /v1/invoices/{id}/finalize`
   */
  finalizeInvoice(
    id: string,
    params?: BodyOf<Op<'finalizeInvoice'>>,
    options?: RequestOptions & IdempotencyOptions,
  ): Promise<ResponseOf<Op<'finalizeInvoice'>>>;
  /**
   * Pay an invoice.
   *
   * Charge a saved card off-session, or record a payment made outside Orbit (`paid_out_of_band`). A decline is a `card_error` carrying the invoice as it now is.
   *
   * `POST /v1/invoices/{id}/pay`
   */
  pay(
    id: string,
    params?: BodyOf<Op<'payInvoice'>>,
    options?: RequestOptions & IdempotencyOptions,
  ): Promise<ResponseOf<Op<'payInvoice'>>>;
  /**
   * Send an invoice to its customer.
   *
   * `POST /v1/invoices/{id}/send`
   */
  sendInvoice(
    id: string,
    params?: BodyOf<Op<'sendInvoice'>>,
    options?: RequestOptions & IdempotencyOptions,
  ): Promise<ResponseOf<Op<'sendInvoice'>>>;
  /**
   * Void an invoice.
   *
   * `POST /v1/invoices/{id}/void`
   */
  voidInvoice(
    id: string,
    params?: BodyOf<Op<'voidInvoice'>>,
    options?: RequestOptions & IdempotencyOptions,
  ): Promise<ResponseOf<Op<'voidInvoice'>>>;
  /**
   * Mark an invoice uncollectible.
   *
   * `POST /v1/invoices/{id}/mark_uncollectible`
   */
  markUncollectible(
    id: string,
    params?: BodyOf<Op<'markInvoiceUncollectible'>>,
    options?: RequestOptions & IdempotencyOptions,
  ): Promise<ResponseOf<Op<'markInvoiceUncollectible'>>>;
  /**
   * List an invoice's lines.
   *
   * Every line, on one page.
   *
   * `GET /v1/invoices/{id}/lines`
   */
  listLineItems(id: string, options?: RequestOptions): ListPromiseOf<Op<'listInvoiceLineItems'>>;
  /**
   * Download an invoice's PDF.
   *
   * `GET /v1/invoices/{id}/pdf`
   */
  retrievePdf(id: string, options?: RequestOptions): Promise<DownloadedBytes>;
  /**
   * Search invoices.
   *
   * Stripe's query language over the invoice's fields and `metadata['key']`.
   *
   * `GET /v1/invoices/search`
   */
  search(
    params: QueryOf<Op<'searchInvoices'>>,
    options?: RequestOptions,
  ): SearchPromiseOf<Op<'searchInvoices'>>;
}

